for(const m of MATERIALS)m.usedBy=ASSEMBLIES.filter(a=>[a.cover,a.cloth].includes(m.id)||m.id==='metal-nickel'||(m.id==='panel-brushed'&&a.finish==='silver')||(m.id==='leather-brown'&&a.finish==='tweed')).map(a=>a.id);
export const assetById=id=>ASSETS.find(a=>a.id===id);
export function assemblyFor(a){return ASSEMBLIES.find(p=>p.id===a.id||(p.study&&p.year===a.year&&p.name===a.name)||(p.id==='deluxe-5e3'&&a.year===1955&&a.name==='Tweed Deluxe')||(p.id==='deluxe-reverb-black'&&a.name==='Deluxe Reverb'&&a.finish==='black')||(p.id==='twin-reverb-early'&&a.name==='Twin Reverb'&&a.year===1968));}
